head.script:
scwin.trigger3_onclick = function(e) {
    var options = {
        "sun": {
            "header": {
                "color": "#ff0000"
            },
            "body": {
                "background": {
                    "background-color": "#ff0000",
                    "opacity": "0.2"
                },
                "num": {
                    "color": "#ff0000"
                }
            }
        },
        "sat": {
            "header": {
                "color": "#0000ff"
            },
            "body": {
                "background": {
                    "background-color": "#0000ff",
                    "opacity": "0.2"
                },
                "num": {
                    "color": "#0000ff"
                }
            }
        }
    };
    schdule1.setDayNameStyle(options);
};
scwin.trigger4_onclick = function(e) {
    //schdule1.setHeaderBtn({"headerLeftBtn":true});
    //schdule1.setHeaderBtn({"headerTitle":true});
    //schdule1.setHeaderBtn({"headerRightBtn":false,"headerLeftBtn":false,"headerTitle":false});
    //schdule1.setHeaderBtn({"headerRightBtn":true});
    schdule1.setHeaderBtn({
        "headerRightBtn": false
    });
};
scwin.rgb2hex = function(rgb) {
    rgb = rgb.match(/^rgba?[\s+]?\([\s+]?(\d+)[\s+]?,[\s+]?(\d+)[\s+]?,[\s+]?(\d+)[\s+]?/i);
    return (rgb && rgb.length === 4) ? "#" +
        ("0" + parseInt(rgb[1], 10).toString(16)).slice(-2) +
        ("0" + parseInt(rgb[2], 10).toString(16)).slice(-2) +
        ("0" + parseInt(rgb[3], 10).toString(16)).slice(-2) : '';
}
scwin._checkRgb = function(rgb, hexa) {
    var color;
    if (rgb.indexOf("rgb") != -1) {
        color = scwin.rgb2hex(rgb);
        return color == hexa;
    }
    return rgb == hexa;
}
scwin.setVal = function() {
    return scwin._checkRgb(WebSquare.wUnit.getJq('#schdule1 tr>td.fc-day:first').css('background-color'), '#ff0000');
}
scwin.setVal1 = function() {
    return scwin._checkRgb(WebSquare.wUnit.getJq('#schdule1 tr>td.fc-day:nth-child(7)').css('background-color'), '#0000ff');
}
scwin.unitTest = function() {
    //init
    // WebSquare.wUnit.start();
    //Test step 1. Source 탭에서 dataList1 을 확인한다.
    //1. In the Source tab, check dataList1.
    //Verify step 1. id = "dataList1" (data list binding)
    //Test step 2. trigger3 function 을 있는지 확인한다.
    //2. Make sure you have trigger3 function.
    //Verify step 2. scwin.trigger3_onclick = function (e)
    //Test step 3. trigger4 function 을 있는지 확인한다.
    //3. Check if trigger4 function exists.
    //Verify step 3. scwin.trigger4_onclick = function (e)
    //Test step 4. 브라우저에서 setDayNameStyle 버튼을 클릭한다.
    //4. In the browser, click the setDayNameStyle button.
    //Verify step 4. The colors of weekends and weekends are changed.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.fc-view-container').length == 1", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger3').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.setVal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.setVal1()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 5. setHeaderBtn 버튼을 클릭한다.
    //5. Click the setHeaderBtn button.
    //Verify step 5. The month, week, and day in the upper right corner disappear.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger4').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.fc-month-button').attr('disabled') == 'disabled'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.fc-basicWeek-button').attr('disabled') == 'disabled'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.fc-basicDay-button').attr('disabled') == 'disabled'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 01-Mar-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
